function isValidBrackets(expr) {
    const stack = [];
    const pairs = { '(': ')', '[': ']', '{': '}' };

    for (const ch of expr) {
        if (ch in pairs) {  // Opening bracket
            stack.push(ch);
        } else if (Object.values(pairs).includes(ch)) {  // Closing
            if (stack.length === 0) return false;
            if (pairs[stack.pop()] !== ch) return false;
        }
    }

    return stack.length === 0;
}
